WITH hourly_stats AS ( SELECT td.t_meal_time, wp.wp_type, td.t_hour, SUM(wr.wr_return_amt) AS hour_return_amt FROM web_returns wr JOIN time_dim td ON wr.wr_returned_time_sk = td.t_time_sk JOIN web_page wp ON wr.wr_web_page_sk = wp.wp_web_page_sk WHERE wp.wp_type = 'product' GROUP BY td.t_meal_time, wp.wp_type, td.t_hour ), with_moving AS ( SELECT t_meal_time, wp_type, t_hour, hour_return_amt, LAG(hour_return_amt) OVER (PARTITION BY t_meal_time ORDER BY t_hour) AS prev_hour_return_amt, SUM(hour_return_amt) OVER (PARTITION BY t_meal_time ORDER BY t_hour ROWS UNBOUNDED PRECEDING) AS cumulative_return_amt FROM hourly_stats ) SELECT t_meal_time, wp_type, t_hour, hour_return_amt, prev_hour_return_amt, cumulative_return_amt, CASE WHEN hour_return_amt = 0 THEN 'No Return' ELSE 'Returned' END AS return_status FROM with_moving ORDER BY t_meal_time, t_hour
